import{_ as n}from"./chunks/settings.DdsESURR.js";import{_ as i,o as t,c as e,a3 as r}from"./chunks/framework.BvvarXmc.js";const s="/screenshots/settings-app-modal.png",o="/screenshots/settings-receipt-modal.png",l="/screenshots/settings-theme-modal.png",P=JSON.parse('{"title":"Pengaturan Umum Sistem (Settings)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-sistem/settings.md","filePath":"panduan-sistem/settings.md","lastUpdated":null}'),g={name:"panduan-sistem/settings.md"};function u(m,a,k,p,d,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="pengaturan-umum-sistem-settings" tabindex="-1">Pengaturan Umum Sistem (Settings) <a class="header-anchor" href="#pengaturan-umum-sistem-settings" aria-label="Permalink to &quot;Pengaturan Umum Sistem (Settings)&quot;">​</a></h1><p>Menu <strong>Pengaturan Aplikasi</strong> adalah pusat kendali konfigurasi operasional, format percetakan dokumen keuangan, serta identitas visual lembaga sekolah di Super Schools.</p><p>Halaman ini dapat diakses oleh Administrator melalui menu <strong>Pengaturan Aplikasi</strong> pada sidebar.</p><hr><h2 id="tampilan-halaman-pengaturan-utama" tabindex="-1">Tampilan Halaman Pengaturan Utama <a class="header-anchor" href="#tampilan-halaman-pengaturan-utama" aria-label="Permalink to &quot;Tampilan Halaman Pengaturan Utama&quot;">​</a></h2><p>Di halaman utama Pengaturan, sistem menampilkan modul konfigurasi dalam bentuk kartu interaktif:</p><p><img src="'+n+'" alt="Halaman Utama Pengaturan"></p><hr><h2 id="_1-modul-pengaturan-aplikasi-app-settings" tabindex="-1">1. Modul Pengaturan Aplikasi (<code>app_settings</code>) <a class="header-anchor" href="#_1-modul-pengaturan-aplikasi-app-settings" aria-label="Permalink to &quot;1. Modul Pengaturan Aplikasi (`app_settings`)&quot;">​</a></h2><p>Modul ini digunakan untuk mengatur profil legal, identitas sekolah, informasi kontak, aturan presensi, dan kategori kepegawaian staf.</p><h3 id="tangkapan-layar-formulir-pengaturan-aplikasi" tabindex="-1">Tangkapan Layar Formulir Pengaturan Aplikasi: <a class="header-anchor" href="#tangkapan-layar-formulir-pengaturan-aplikasi" aria-label="Permalink to &quot;Tangkapan Layar Formulir Pengaturan Aplikasi:&quot;">​</a></h3><p><img src="'+s+'" alt="Formulir Pengaturan Aplikasi"></p><h3 id="rincian-bidang-fungsinya" tabindex="-1">Rincian Bidang &amp; Fungsinya: <a class="header-anchor" href="#rincian-bidang-fungsinya" aria-label="Permalink to &quot;Rincian Bidang &amp; Fungsinya:&quot;">​</a></h3><ol><li><p><strong>Logo Sekolah</strong>:</p><ul><li><strong>Fungsi</strong>: Mengunggah gambar logo resmi sekolah (format PNG transparan atau JPG, ukuran maksimal 2 MB).</li><li><strong>Penempatan</strong>: Logo ini otomatis muncul pada header portal, kop surat resmi, kartu pelajar digital, dan kop laporan akademik.</li><li><strong>Ikon Hapus (Tong Sampah)</strong>: Digunakan untuk menghapus logo yang sudah ada jika ingin mengganti logo baru.</li></ul></li><li><p><strong>Nama Sekolah</strong>:</p><ul><li><strong>Fungsi</strong>: Nama resmi lembaga sekolah (contoh: <code>MTsN 3 Ponorogo</code>).</li><li><strong>Pengaruh</strong>: Ditampilkan pada judul aplikasi, kop rapor, dan identitas pengirim pesan/tagihan.</li></ul></li><li><p><strong>Alamat Lengkap</strong>:</p><ul><li><strong>Fungsi</strong>: Alamat domisili fisik sekolah beserta nama jalan, nomor, kelurahan/desa, dan kecamatan.</li><li><strong>Pengaruh</strong>: Dicantumkan pada kop seluruh surat dan dokumen yang diterbitkan sistem.</li></ul></li><li><p><strong>Telepon</strong>:</p><ul><li><strong>Fungsi</strong>: Nomor telepon resmi tata usaha atau kantor sekolah (contoh: <code>+62 123 456 789</code>).</li><li><strong>Pengaruh</strong>: Muncul sebagai kontak darurat dan bantuan di portal siswa dan wali murid.</li></ul></li><li><p><strong>Email</strong>:</p><ul><li><strong>Fungsi</strong>: Alamat email resmi sekolah (contoh: <code>info@sekolah.com</code>).</li><li><strong>Pengaruh</strong>: Digunakan sebagai identitas kontak resmi dan tujuan balasan surel otomatis.</li></ul></li><li><p><strong>Aktifkan Poin Absensi (Centang/Checkbox)</strong>:</p><ul><li><strong>Fungsi</strong>: Mengaktifkan sistem kalkulasi poin otomatis pada presensi siswa.</li><li><strong>Cara Kerja</strong>: Jika dicentang, setiap kali siswa melakukan absensi (baik melalui mesin RFID atau input guru), sistem secara otomatis mengakumulasikan skor kedisiplinan (misal: <em>Hadir tepat waktu = +2 poin</em>, <em>Terlambat = +1 poin</em>, <em>Alpha = 0 poin</em>). Poin ini dapat digunakan sekolah untuk penilaian kedisiplinan dan penghargaan siswa teladan.</li></ul></li><li><p><strong>Status Kepegawaian Guru</strong>:</p><ul><li><strong>Fungsi</strong>: Mengatur kategori ikatan kerja guru dan tenaga kependidikan di sekolah (seperti: PNS, PPPK, Guru Tetap Yayasan, GTT, Honorer).</li><li><strong>Tombol Reset Default</strong>: Mengembalikan daftar kategori ke konfigurasi standar kementerian.</li></ul></li></ol><h3 id="alur-mengubah-pengaturan-aplikasi" tabindex="-1">Alur Mengubah Pengaturan Aplikasi: <a class="header-anchor" href="#alur-mengubah-pengaturan-aplikasi" aria-label="Permalink to &quot;Alur Mengubah Pengaturan Aplikasi:&quot;">​</a></h3><ol><li>Pada kartu <strong>Pengaturan Aplikasi</strong>, klik tombol <strong>Edit</strong>.</li><li>Jendela modal formulir akan terbuka. Sesuaikan informasi yang diperlukan.</li><li>Klik tombol <strong>Simpan Pengaturan</strong> di bagian bawah jendela modal.</li></ol><hr><h2 id="_2-modul-pengaturan-nota-receipt-settings" tabindex="-1">2. Modul Pengaturan Nota (<code>receipt_settings</code>) <a class="header-anchor" href="#_2-modul-pengaturan-nota-receipt-settings" aria-label="Permalink to &quot;2. Modul Pengaturan Nota (`receipt_settings`)&quot;">​</a></h2><p>Modul ini bertanggung jawab mengatur tata letak, kop dokumen, format teks, dan ukuran kertas untuk seluruh bukti pembayaran kasir, kuitansi SPP, dan struk belanja kantin sekolah.</p><h3 id="tangkapan-layar-formulir-pengaturan-nota" tabindex="-1">Tangkapan Layar Formulir Pengaturan Nota: <a class="header-anchor" href="#tangkapan-layar-formulir-pengaturan-nota" aria-label="Permalink to &quot;Tangkapan Layar Formulir Pengaturan Nota:&quot;">​</a></h3><p><img src="'+o+'" alt="Formulir Pengaturan Nota"></p><h3 id="rincian-bidang-fungsinya-1" tabindex="-1">Rincian Bidang &amp; Fungsinya: <a class="header-anchor" href="#rincian-bidang-fungsinya-1" aria-label="Permalink to &quot;Rincian Bidang &amp; Fungsinya:&quot;">​</a></h3><ol><li><p><strong>Logo Nota</strong>:</p><ul><li><strong>Fungsi</strong>: Mengunggah logo instansi atau lambang komite sekolah yang dicetak di atas kuitansi bukti pembayaran.</li></ul></li><li><p><strong>Judul Nota</strong>:</p><ul><li><strong>Fungsi</strong>: Baris judul teratas pada kop bukti pembayaran (contoh: <code>Komite MTsN 3 Ponorogo</code> atau <code>Loket Pembayaran SPP</code>).</li></ul></li><li><p><strong>Sub Judul</strong>:</p><ul><li><strong>Fungsi</strong>: Keterangan pelengkap di bawah judul utama (contoh: <code>Madrasah Tsanawiyah Negeri 3 Ponorogo</code>).</li></ul></li><li><p><strong>Nama Sekolah</strong>:</p><ul><li><strong>Fungsi</strong>: Nama sekolah yang dicetak di bagian badan kuitansi resmi.</li></ul></li><li><p><strong>Alamat</strong>:</p><ul><li><strong>Fungsi</strong>: Alamat lengkap lokasi loket kasir atau tata usaha yang tercetak pada kop kuitansi.</li></ul></li><li><p><strong>Kontak</strong>:</p><ul><li><strong>Fungsi</strong>: Nomor telepon/WhatsApp loket kasir sekolah (contoh: <code>(0352) 483779</code>) agar wali murid dapat menghubungi bendahara jika ada kekeliruan pencatatan tagihan.</li></ul></li><li><p><strong>Catatan Kaki (Footer Note)</strong>:</p><ul><li><strong>Fungsi</strong>: Teks pesan himbauan di bagian terbawah struk kuitansi (contoh: <em>&quot;Simpan tanda terima ini sebagai bukti pembayaran yang sah. Terima kasih atas kerja sama Anda.&quot;</em>).</li></ul></li><li><p><strong>Format Tanda Tangan Penyetor &amp; Penerima</strong>:</p><ul><li><strong>Penyetor (Kiri)</strong>: Label nama penandatangan sebelah kiri (default: <em>Penyetor / Wali Murid</em>).</li><li><strong>Penerima (Kanan)</strong>: Label nama penandatangan sebelah kanan (default: <em>Penerima / Bendahara Sekolah</em>).</li></ul></li><li><p><strong>Opsi Tampilan Tambahan</strong>:</p><ul><li><strong>Tampilkan Status Lunas</strong>: Mencetak stempel tulisan status <strong>LUNAS</strong> secara otomatis pada struk jika pembayaran sudah tuntas.</li><li><strong>Tampilkan Tabel Riwayat Angsuran</strong>: Menampilkan riwayat cicilan sebelumnya jika tagihan dibayar secara bertahap.</li></ul></li><li><p><strong>Ukuran Kertas Cetak</strong>:</p><ul><li><strong>Ukuran Kertas Pembayaran SPP</strong>: Pilihan ukuran kertas lembar kuitansi besar (<strong>A4</strong>, <strong>A5</strong>, atau ukuran kasir <strong>A8</strong>).</li><li><strong>Ukuran Kertas Kasir Kantin</strong>: Disesuaikan dengan printer thermal kasir mini (<strong>A8 / 58mm &amp; 80mm</strong>).</li><li><strong>Ukuran Kertas Top-Up Saldo</strong>: Format struk bukti pengisian saldo kartu digital siswa (<strong>A8</strong>).</li></ul></li></ol><h3 id="alur-mengubah-pengaturan-nota" tabindex="-1">Alur Mengubah Pengaturan Nota: <a class="header-anchor" href="#alur-mengubah-pengaturan-nota" aria-label="Permalink to &quot;Alur Mengubah Pengaturan Nota:&quot;">​</a></h3><ol><li>Pada kartu <strong>Pengaturan Nota</strong>, klik tombol <strong>Edit</strong>.</li><li>Sesuaikan kop kuitansi, catatan kaki, serta ukuran kertas printer yang digunakan sekolah Anda.</li><li>Klik tombol <strong>Simpan Pengaturan</strong>.</li></ol><hr><h2 id="_3-modul-tema-branding-sekolah-custom-theme" tabindex="-1">3. Modul Tema &amp; Branding Sekolah (<code>custom_theme</code>) <a class="header-anchor" href="#_3-modul-tema-branding-sekolah-custom-theme" aria-label="Permalink to &quot;3. Modul Tema &amp; Branding Sekolah (`custom_theme`)&quot;">​</a></h2><p>Modul ini memberikan kebebasan bagi Administrator sekolah untuk menyesuaikan tampilan estetika aplikasi agar selaras dengan identitas, warna almamater, atau ciri khas madrasah/sekolah masing-masing.</p><h3 id="tangkapan-layar-modal-tema-branding" tabindex="-1">Tangkapan Layar Modal Tema &amp; Branding: <a class="header-anchor" href="#tangkapan-layar-modal-tema-branding" aria-label="Permalink to &quot;Tangkapan Layar Modal Tema &amp; Branding:&quot;">​</a></h3><p><img src="'+l+'" alt="Atur Tema &amp; Tampilan Sekolah"></p><h3 id="rincian-pilihan-fungsinya" tabindex="-1">Rincian Pilihan &amp; Fungsinya: <a class="header-anchor" href="#rincian-pilihan-fungsinya" aria-label="Permalink to &quot;Rincian Pilihan &amp; Fungsinya:&quot;">​</a></h3><ol><li><p><strong>Pilihan Preset Tema Sistem</strong>: Sistem menyediakan 8 kombinasi palet warna siap pakai yang dirancang profesional untuk institusi pendidikan:</p><ul><li><strong>Academic Navy</strong>: Kombinasi warna biru dongker formal berwibawa, sangat cocok untuk sekolah umum dan SMA/SMK.</li><li><strong>Madrasah Green</strong>: Perpaduan hijau botol khas Kementerian Agama dan pesantren, ideal untuk MTs, MA, dan pondok pesantren.</li><li><strong>Ocean Blue</strong>: Warna biru muda cerah yang ramah dan segar, sangat cocok untuk jenjang SD dan SMP.</li><li><strong>Forest Green</strong>: Warna hijau alami yang memberikan kesan sejuk dan bersahabat.</li><li><strong>Warm Orange</strong>: Warna oranye energik dan kreatif, cocok untuk sekolah berbasis kejuruan dan seni.</li><li><strong>Elite Maroon</strong>: Warna merah marun elegan untuk institusi bergengsi dan akademi.</li><li><strong>Tech Teal</strong>: Warna hijau toska modern bernuansa sains dan teknologi.</li><li><strong>Classic Indigo</strong>: Warna nila klasik modern dengan aksen warna yang tajam.</li></ul></li><li><p><strong>Kustomisasi Mandiri (Custom Color Picker)</strong>: Jika sekolah memiliki standar warna khusus (HEX Code), admin dapat memilih opsi <strong>Kustomisasi</strong>:</p><ul><li><strong>Warna Utama (Primary Color)</strong>: Mengubah warna tombol utama, warna sorotan menu aktif di sidebar, serta latar belakang header.</li><li><strong>Warna Sekunder (Secondary Color)</strong>: Mengatur warna tombol bantuan, kartu statistik, dan aksen latar belakang lembut.</li><li><strong>Warna Aksen (Accent Color)</strong>: Mengatur warna status khusus, lencana penting (<em>badges</em>), dan tombol penegas aksi.</li></ul></li><li><p><strong>Mode Tampilan Visual</strong>:</p><ul><li><strong>Mode Terang (Light Mode)</strong>: Latar belakang putih bersih untuk penggunaan siang hari di ruang kantor yang terang.</li><li><strong>Mode Gelap (Dark Mode)</strong>: Latar belakang gelap ramah mata untuk kenyamanan penggunaan jangka panjang.</li></ul></li></ol><h3 id="alur-mengubah-tema-aplikasi" tabindex="-1">Alur Mengubah Tema Aplikasi: <a class="header-anchor" href="#alur-mengubah-tema-aplikasi" aria-label="Permalink to &quot;Alur Mengubah Tema Aplikasi:&quot;">​</a></h3><ol><li>Pada kartu <strong>Tema &amp; Branding</strong>, klik tombol <strong>Atur Tema</strong>.</li><li>Klik salah satu kotak preset tema yang diinginkan, atau masukkan kode warna HEX kustom sekolah Anda.</li><li>Klik tombol <strong>Simpan Tema</strong>.</li><li>Halaman aplikasi akan otomatis diperbarui dan seluruh elemen antarmuka akan langsung berganti warna mengikuti tema yang Anda pilih.</li></ol>',34)])])}const y=i(g,[["render",u]]);export{P as __pageData,y as default};
